import{_ as e,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"الأسئلة الشائعة","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ar/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ar/faq/"}],["meta",{"property":"og:title","content":"الأسئلة الشائعة | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"بيانات Monster Hunter والبحث عن تشكيلات الدروع في Wilds وRise مع Sunbreak وWorld مع Iceborne."}]]},"headers":[],"relativePath":"ar/faq/index.md","filePath":"ar/faq/index.md"}'),i={name:"ar/faq/index.md"};function n(l,a,s,h,p,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="الأسئلة-الشائعة" tabindex="-1">الأسئلة الشائعة <a class="header-anchor" href="#الأسئلة-الشائعة" aria-label="Permalink to &quot;الأسئلة الشائعة&quot;">​</a></h1><h2 id="ما-الألعاب-المدعومة؟" tabindex="-1">ما الألعاب المدعومة؟ <a class="header-anchor" href="#ما-الألعاب-المدعومة؟" aria-label="Permalink to &quot;ما الألعاب المدعومة؟&quot;">​</a></h2><p>يدعم Wilds وRise مع Sunbreak وWorld مع Iceborne. تبقى بيانات كل لعبة وآلياتها منفصلة، ويمكن اختيار اللعبة من الشاشة الرئيسية.</p><h2 id="أين-يمكن-تنزيل-التطبيق؟" tabindex="-1">أين يمكن تنزيل التطبيق؟ <a class="header-anchor" href="#أين-يمكن-تنزيل-التطبيق؟" aria-label="Permalink to &quot;أين يمكن تنزيل التطبيق؟&quot;">​</a></h2><p>يتوفر إصدار Android على <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> وإصدار HarmonyOS على <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. إصدار iOS قيد الإعداد للنشر. راجع قسم <a href="./../#download">التنزيل</a>؛ يختلف التوفر حسب المنطقة والجهاز.</p><h2 id="هل-يعمل-دون-اتصال؟" tabindex="-1">هل يعمل دون اتصال؟ <a class="header-anchor" href="#هل-يعمل-دون-اتصال؟" aria-label="Permalink to &quot;هل يعمل دون اتصال؟&quot;">​</a></h2><p>البيانات مضمّنة في التطبيق. يعمل التصفح والبحث والمفضلة والبحث عن الدروع محليًا. تتطلب المواقع الخارجية وتنزيل التحديثات اتصالًا بالإنترنت.</p><h2 id="كيف-يعمل-البحث-عن-الدروع؟" tabindex="-1">كيف يعمل البحث عن الدروع؟ <a class="header-anchor" href="#كيف-يعمل-البحث-عن-الدروع؟" aria-label="Permalink to &quot;كيف يعمل البحث عن الدروع؟&quot;">​</a></h2><p>حدّد المهارات ومستوياتها، وثبّت المعدات أو استبعدها، وقيّد الزينات بما تملكه. يدعم Rise أيضًا التعاويذ والدروع المعززة التي تملكها. تعتمد النتائج على البيانات والشروط المختارة؛ ولا تحسب هذه الميزة الضرر.</p><h2 id="ما-اللغات-المتاحة؟" tabindex="-1">ما اللغات المتاحة؟ <a class="header-anchor" href="#ما-اللغات-المتاحة؟" aria-label="Permalink to &quot;ما اللغات المتاحة؟&quot;">​</a></h2><p>يوفر التطبيق 14 لغة. قد تبقى بعض نصوص اللعبة بالإنجليزية. عند غياب نص بالإسبانية لأمريكا اللاتينية، يُستخدم نص الإسبانية لإسبانيا أولًا، ثم الإنجليزية.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="هل-هذا-تطبيق-رسمي؟" tabindex="-1">هل هذا تطبيق رسمي؟ <a class="header-anchor" href="#هل-هذا-تطبيق-رسمي؟" aria-label="Permalink to &quot;هل هذا تطبيق رسمي؟&quot;">​</a></h2><p>لا. هذا تطبيق مستقل من تطوير المعجبين، ولا يرتبط بـCAPCOM ولا يحظى باعتمادها. تعود صور Monster Hunter وبياناته إلى CAPCOM Co., Ltd.</p>',14)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
